CREATE OR REPLACE FUNCTION public.evaluation_save_activity(p_actor text,p_activity jsonb,p_criteria jsonb) RETURNS uuid LANGUAGE plpgsql SET search_path=public AS $$ DECLARE aid uuid:=coalesce((p_activity->>'id')::uuid,gen_random_uuid()); old public."Evaluation_Activities"; x jsonb; tid text; BEGIN SELECT * INTO old FROM public."Evaluation_Activities" WHERE id=aid FOR UPDATE; IF FOUND AND old.state<>'Draft' THEN RAISE EXCEPTION 'Published activity immutable'; END IF; IF NOT public.evaluation_can(p_actor,p_activity->>'module',CASE WHEN old.id IS NULL THEN 'a' ELSE 'e' END) THEN RAISE EXCEPTION 'Not authorized'; END IF; FOR tid IN SELECT jsonb_array_elements_text(p_activity->'team_ids') LOOP IF NOT public.evaluation_can(p_actor,p_activity->>'module',CASE WHEN old.id IS NULL THEN 'a' ELSE 'e' END,tid) THEN RAISE EXCEPTION 'Team not authorized'; END IF; END LOOP; INSERT INTO public."Evaluation_Activities"(id,module,title,description,audience,team_ids,beneficiary_ids,leader_ids,starts_at,ends_at,publish_at,max_attempts,state,attendance_points,excused_enabled,excused_points,season,created_by,image_url,template_id,max_points,reveal_answers,linked_record) VALUES(aid,p_activity->>'module',p_activity->>'title',p_activity->>'description',p_activity->>'audience',ARRAY(SELECT jsonb_array_elements_text(p_activity->'team_ids')),ARRAY(SELECT jsonb_array_elements_text(p_activity->'beneficiary_ids')),ARRAY(SELECT jsonb_array_elements_text(p_activity->'leader_ids')),(p_activity->>'starts_at')::timestamptz,(p_activity->>'ends_at')::timestamptz,(p_activity->>'publish_at')::timestamptz,(p_activity->>'max_attempts')::integer,p_activity->>'state',(p_activity->>'attendance_points')::numeric,(p_activity->>'excused_enabled')::boolean,(p_activity->>'excused_points')::numeric,p_activity->>'season',p_actor,p_activity->>'image_url',(p_activity->>'template_id')::uuid,(p_activity->>'max_points')::numeric,p_activity->>'reveal_answers',p_activity->>'linked_record') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,description=EXCLUDED.description,audience=EXCLUDED.audience,team_ids=EXCLUDED.team_ids,beneficiary_ids=EXCLUDED.beneficiary_ids,leader_ids=EXCLUDED.leader_ids,starts_at=EXCLUDED.starts_at,ends_at=EXCLUDED.ends_at,publish_at=EXCLUDED.publish_at,max_attempts=EXCLUDED.max_attempts,state=EXCLUDED.state,attendance_points=EXCLUDED.attendance_points,excused_enabled=EXCLUDED.excused_enabled,excused_points=EXCLUDED.excused_points,season=EXCLUDED.season,image_url=EXCLUDED.image_url,template_id=EXCLUDED.template_id,max_points=EXCLUDED.max_points,reveal_answers=EXCLUDED.reveal_answers,linked_record=EXCLUDED.linked_record;
 DELETE FROM public."Evaluation_Criteria" WHERE activity_id=aid;
 FOR x IN SELECT * FROM jsonb_array_elements(p_criteria) LOOP INSERT INTO public."Evaluation_Criteria"(activity_id,title,points,sort_order,options,correct_option,question_id,description,image_url) VALUES(aid,x->>'title',(x->>'points')::numeric,(x->>'sort_order')::integer,coalesce(x->'options','[]'),(x->>'correct_option')::integer,(x->>'question_id')::uuid,coalesce(x->>'description',''),coalesce(x->>'image_url','')); END LOOP;
 INSERT INTO public."Evaluation_Changes"(entity_type,entity_id,actor_id,action,snapshot) VALUES('activity',aid::text,p_actor,'save',jsonb_build_object('activity',p_activity,'criteria',p_criteria)); RETURN aid; END $$;
CREATE OR REPLACE FUNCTION public.evaluation_delete_draft(p_id uuid,p_actor text) RETURNS void LANGUAGE plpgsql SET search_path=public AS $$ DECLARE a public."Evaluation_Activities"; BEGIN SELECT * INTO a FROM public."Evaluation_Activities" WHERE id=p_id FOR UPDATE; IF NOT FOUND OR a.state<>'Draft' OR NOT public.evaluation_can(p_actor,a.module,'d') OR EXISTS(SELECT 1 FROM public."Evaluation_Results" WHERE activity_id=p_id) THEN RAISE EXCEPTION 'Draft cannot be deleted'; END IF; DELETE FROM public."Evaluation_Criteria" WHERE activity_id=p_id; DELETE FROM public."Evaluation_Activities" WHERE id=p_id; END $$;
CREATE OR REPLACE FUNCTION public.evaluation_notify_points() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE recipient text; BEGIN IF EXISTS(SELECT 1 FROM public."Evaluation_Settings" WHERE id='main' AND config->>'notifications'='false') THEN RETURN NEW; END IF; IF TG_OP='INSERT' THEN FOR recipient IN SELECT DISTINCT user_id FROM public."Evaluation_Permissions" WHERE screen='points_approval' AND actions LIKE '%r%' AND actions LIKE '%e%' AND (general_access OR (team_id<>'' AND team_id=NEW.team_id)) LOOP INSERT INTO public."User_Notifications"("Notification_ID","User_ID","Title","Body","Created_At","Is_Read","Source","Reference_ID") VALUES(gen_random_uuid()::text,recipient,'طلب نقاط جديد',NEW.description,now()::text,'False','evaluation_pending',NEW.id::text); END LOOP; ELSE INSERT INTO public."User_Notifications"("Notification_ID","User_ID","Title","Body","Created_At","Is_Read","Source","Reference_ID") VALUES(gen_random_uuid()::text,NEW.user_id,CASE WHEN NEW.status='Approved' THEN 'تم اعتماد نقاطك' ELSE 'تم رفض طلب النقاط' END,NEW.description||' — '||NEW.amount::text||coalesce(' — '||NEW.rejection_reason,''),now()::text,'False','evaluation_review',NEW.id::text); END IF; RETURN NEW; END $$;
CREATE TRIGGER evaluation_notify_after AFTER INSERT OR UPDATE ON public."Points_Transactions" FOR EACH ROW EXECUTE FUNCTION public.evaluation_notify_points();
REVOKE ALL ON FUNCTION public.evaluation_save_activity(text,jsonb,jsonb),public.evaluation_delete_draft(uuid,text),public.evaluation_notify_points() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.evaluation_save_activity(text,jsonb,jsonb),public.evaluation_delete_draft(uuid,text) TO service_role;